import './style.css';
import {createIcons,AudioLines,Compass,MessagesSquare,UserRound,MapPin,SlidersHorizontal,ArrowRight,ArrowUpRight,X,Heart,Plus,Play,Pause,ChevronRight,ChevronLeft,Check,Headphones,Music2,Disc3,ShieldCheck,LogOut,Flag,Ban,MoreHorizontal,Send,Upload,Volume2,Radio,Users,Mic2,Settings2,RotateCcw,Trash2,LoaderCircle,Globe,CheckCheck,ExternalLink} from 'lucide';
import {GraffitiDecentralized} from '@graffiti-garden/implementation-decentralized';
import {INSTRUMENTS,GENRES,INTENTS,CITIES,MAX_BYTES,coarse,latest,profiles,blocks,connections,conversation,discover,validateProfile,validateMedia} from './domain.js';
import {Repository} from './repository.js';
import {DemoAPI,seed} from './demo.js';
import {bindSessions} from './auth.js';
const icons={AudioLines,Compass,MessagesSquare,UserRound,MapPin,SlidersHorizontal,ArrowRight,ArrowUpRight,X,Heart,Plus,Play,Pause,ChevronRight,ChevronLeft,Check,Headphones,Music2,Disc3,ShieldCheck,LogOut,Flag,Ban,MoreHorizontal,Send,Upload,Volume2,Radio,Users,Mic2,Settings2,RotateCcw,Trash2,LoaderCircle,Globe,CheckCheck,ExternalLink};
const app=document.querySelector('#app'),overlays=document.querySelector('#overlays');
const moderator=import.meta.env.VITE_MODERATOR_ACTOR||'';
const state={session:null,repo:null,rows:[],page:'discover',loading:true,restoring:true,error:'',demo:false,step:0,editing:false,chat:null,unread:0};
let epoch=0,timer,refreshing=false,modalReturn,modalCleanup,toastTimer,actionBusy=false;
const pendingOps=new Map();const mediaURLs=new Map();
const workspace=window.parent!==window?window.parent.gtWorkspace:null;
const graff=workspace?.createClient({blobConstructor:Blob})||new GraffitiDecentralized();
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name,cls='')=>`<i data-lucide="${name}" class="${cls}" aria-hidden="true"></i>`;
const brand=()=>`<span class="brand-mark">${icon('audio-lines')}</span><span>yudo<span class="brand-dot">.</span></span>`;
const me=()=>state.session?.actor;
const own=()=>latest(state.rows,'profile',me())?.value;
const settings=()=>latest(state.rows,'settings',me())?.value||{radius:25,instruments:[],genres:[],intent:'',notifications:true};
const matches=()=>connections(state.rows,me());
const nameOf=a=>latest(state.rows,'profile',a)?.value.name||'Musician';
const list=a=>(a||[]).map(e).join(' · ');
function paint(){createIcons({icons,attrs:{'stroke-width':1.7}});loadImages();}
function toast(message){const el=document.querySelector('#announcements');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),6500)}
function clearMedia(){document.querySelectorAll('audio,video').forEach(x=>x.pause());for(const u of mediaURLs.values())URL.revokeObjectURL(u);mediaURLs.clear()}
async function mediaURL(url){if(mediaURLs.has(url))return mediaURLs.get(url);const repo=state.repo,id=epoch,blob=await repo.media(url);if(id!==epoch)throw Error('Account changed.');const value=URL.createObjectURL(blob);mediaURLs.set(url,value);return value;}
function avatar(p,size=''){return `<span class="avatar ${size}">${p?.avatar?`<img data-media="${e(p.avatar)}" alt="${e(p.name)}">`:`${e((p?.name||'M').split(' ').map(s=>s[0]).slice(0,2).join(''))}`}</span>`}
function loadImages(){document.querySelectorAll('img[data-media]').forEach(async img=>{const url=img.dataset.media;delete img.dataset.media;try{img.src=await mediaURL(url)}catch{img.alt='Profile image unavailable'}})}
function render(){document.querySelectorAll('audio,video').forEach(x=>x.pause());if(!state.session){welcome();return}if(state.loading){app.innerHTML=`<div class="loading">${brand()}<p>${icon('loader-circle','spin')} Finding your rhythm…</p></div>`;paint();return}if(state.error&&!own()&&!state.rows.length){app.innerHTML=`<div class="loading"><div class="brand">${brand()}</div><h2>Your profile couldn’t load.</h2><p>${e(state.error)}</p><button class="primary" data-action="reload-session">Try again</button><button class="quiet" data-action="logout">Log out</button></div>`;paint();return}if(!own()||state.editing){onboarding();return}
 const p=own(),count=matches().length;
 app.innerHTML=`<div class="shell"><aside class="sidebar"><a class="brand" href="/" aria-label="Yudo home">${brand()}</a><p class="sidebar-caption">GOOD PEOPLE. GREAT MUSIC.</p><nav aria-label="Main navigation">${[['discover','compass','Discover'],['connections','messages-square','Connections'],['profile','user-round','My profile']].map(([id,ic,label])=>`<button class="nav-item ${state.page===id?'active':''}" data-page="${id}" ${state.page===id?'aria-current="page"':''}>${icon(ic)}<span>${label}</span>${id==='connections'&&count?`<b class="count">${count}</b>`:''}</button>`).join('')}</nav><div class="sidebar-note"><span class="tiny-label">A LITTLE REMINDER</span>${icon('disc-3')}<p>Your next favorite bandmate is out there.</p><span>Start with a hello.</span></div><div class="sidebar-bottom"><button data-action="privacy" class="quiet">${icon('shield-check')} Your space, your choice</button><button class="account" data-page="profile">${avatar(p)}<span><strong>${e(p.name)}</strong><small>${state.demo?'Demo musician':'Your musician profile'}</small></span>${icon('chevron-right')}</button></div></aside><main class="main"><header class="topbar"><div class="mobile-logo brand">${brand()}</div><span class="breadcrumb">YOUR NEXT CHAPTER STARTS HERE</span><div class="top-actions"><span class="location-label">${icon('map-pin')}${e(p.location.city)}</span><button class="icon-button" data-action="filters" aria-label="Discovery settings">${icon('settings-2')}</button></div></header>${state.demo?`<div class="demo-banner"><span>Demo workspace · fictional musicians · saved in this browser</span><button data-action="login">Use Graffiti ${icon('arrow-up-right')}</button></div>`:''}<div class="content">${state.error?`<div class="error">${e(state.error)} <button data-action="refresh">Try again</button></div>`:''}${state.page==='discover'?discoveryPage():state.page==='connections'?connectionsPage():profilePage()}</div><footer class="page-footer"><span>LESS SCROLLING. MORE JAMMING.</span><span>Made for the way you make music ${icon('audio-lines')}</span></footer></main></div>`;paint();if(state.page==='connections'&&state.chat)loadChatScroll();}
function welcome(){app.innerHTML=`<div class="welcome"><section class="welcome-art"><a class="brand" href="/">${brand()}</a><div class="welcome-copy"><span class="eyebrow">FIND YOUR PEOPLE. MAKE YOUR SOUND.</span><h1>Great music<br>starts with<br><em>good chemistry.</em></h1><p>A bandmate. A session player. Your next creative spark.<br>Find musicians who get your sound.</p><div class="welcome-tags"><span>${icon('users')} Form a band</span><span>${icon('radio')} Play live</span><span>${icon('mic-2')} Record together</span></div></div><div class="record-art" aria-hidden="true"><div class="record-label">SOUND<br>CHECK<span>SIDE A · NEW BEGINNINGS</span></div></div><span class="welcome-footer">ONE CONNECTION CAN CHANGE YOUR SOUND.</span></section><section class="welcome-panel"><span class="eyebrow">YOUR NEXT CHAPTER</span><h2>A little less searching.<br>A lot more playing.</h2><p>Tell your story. Hear their sound.<br>Connect when the feeling is mutual.</p>${state.restoring?`<div class="restore">${icon('loader-circle','spin')} Restoring your session…</div>`:`<button class="primary full" data-action="login">Continue with Graffiti ${icon('arrow-right')}</button>`}<p class="login-note">Your account, powered by Graffiti.<br>Sign in or create an account in the next step.</p><div class="divider"><span>TAKE IT FOR A SPIN</span></div><button class="outline full" data-action="demo">${icon('headphones')} Explore the demo ${icon('arrow-up-right')}</button><p class="small muted">Fictional profiles. No account needed.</p>${state.error?`<div class="error" role="alert">${e(state.error)}</div>`:''}<div class="welcome-trust">${icon('shield-check')} For musicians 18+. You choose what to publish.</div></section></div>`;paint()}
function art(p,variant=''){const role=p.instruments?.[0]||'Music';return `<div class="music-art ${variant}" aria-label="${e(role)} artwork"><div class="art-top"><span>YUDO SELECTS</span>${icon('audio-lines')}</div><div class="art-orbit orbit-one"></div><div class="art-orbit orbit-two"></div><div class="art-type">${role==='Drums'?'IN THE<br>POCKET.':role==='Bass'?'FEEL THE<br>LOW END.':role==='Vocals'?'FIND YOUR<br>VOICE.':role==='Keys'?'A NEW<br>KEY.':'MAKE<br>WAVES.'}</div><div class="art-disc"><span>${icon(role==='Vocals'?'mic-2':role==='Drums'?'disc-3':'music-2')}</span></div><div class="art-bottom"><span>${e(role.toUpperCase())} / ${e((p.genres?.[0]||'YOUR SOUND').toUpperCase())}</span><span>VOL. 01</span></div></div>`}
function discoveryPage(){const s=settings(),rows=discover(state.rows,me(),s,state.demo?'demo:moderator':moderator),item=rows[0],p=item?.object.value;
 return `<section class="page-heading"><div><div class="eyebrow">A LITTLE CREATIVE CHEMISTRY</div><h1>Find your people<span class="accent">.</span></h1><p>Different backgrounds. Shared wavelengths. Something good starts here.</p></div><span class="heading-doodle" aria-hidden="true">${icon('audio-lines')}</span></section><div class="filter-bar"><div class="filter-pills"><button data-action="filters">${icon('map-pin')} Within ${s.radius||25} miles ${icon('chevron-right')}</button><button data-action="filters">${icon('music-2')}${s.instruments?.length?e(s.instruments.join(', ')):'All instruments'}</button><button data-action="filters">${icon('users')}${s.intent?e(INTENTS[s.intent]):'All opportunities'}</button></div><button class="filter-edit" data-action="filters">${icon('sliders-horizontal')}<span>Filters</span>${s.genres?.length?'<b class="filter-dot"></b>':''}</button></div><div class="discovery-layout"><section class="discovery-main" aria-label="Musician discovery">${p?`<div class="discovery-caption"><span><i class="status-dot"></i> ON YOUR WAVELENGTH</span><span>${rows.length} musician${rows.length===1?'':'s'} to discover</span></div><article class="musician-card" id="swipe-card" data-actor="${e(item.object.actor)}"><div class="card-visual">${p.avatar?`<img class="cover-photo" data-media="${e(p.avatar)}" alt="${e(p.name)}">`:art(p)}<span class="role-badge">${icon('music-2')}${e(p.instruments[0])}</span><button class="card-more icon-button" data-menu="${e(item.object.actor)}" aria-label="Profile options">${icon('more-horizontal')}</button><div class="visual-caption">${icon('headphones')} LISTEN FIRST. CONNECT NATURALLY.</div></div><div class="card-details"><span class="intent-tag">${icon('users')}${p.openTo.includes('band')?'Open to forming a band':e(INTENTS[p.openTo[0]]||INTENTS[p.seeking[0]]||'Open to connecting')}</span><button class="name-button" data-view="${e(item.object.actor)}"><h2>${e(p.name)}</h2>${icon('arrow-up-right')}</button><div class="musician-location">${icon('map-pin')}${e(p.location.city)}<span>·</span>about ${Math.max(1,Math.round(item.miles))} mi away</div><div class="tags">${p.instruments.map(x=>`<span class="instrument-tag">${e(x)}</span>`).join('')}${p.genres.slice(0,3).map(x=>`<span>${e(x)}</span>`).join('')}</div><p class="card-bio">${e(p.bio||'The next good collaboration starts with a conversation.')}</p><div class="inspirations"><span class="tiny-label">ON REPEAT</span><p>${list(p.inspirations)||'Still finding new favorites'}</p></div>${sampleCard(p.samples?.[0])}<div class="compatibility">${icon('audio-lines')}<span>${item.genres?`${item.genres} shared genre${item.genres===1?'':'s'}`:'A different sound to explore'}${item.intentFit?' · Compatible opportunities':''}</span></div><button class="text-link" data-view="${e(item.object.actor)}">Get to know ${e(p.name.split(' ')[0])}${icon('arrow-right')}</button></div></article><div class="swipe-actions"><button class="swipe pass" data-pass="${e(item.object.actor)}" aria-label="Pass on ${e(p.name)}">${icon('x')}</button><button class="swipe expand" data-view="${e(item.object.actor)}" aria-label="View full profile">${icon('user-round')}</button><button class="swipe like" data-like="${e(item.object.actor)}" aria-label="Like ${e(p.name)}">${icon('heart')}</button></div><p class="swipe-hint">Pass <span>←</span><i></i> A good feeling? Say hello. <i></i><span>→</span> Connect</p>`:`<div class="empty discovery-empty">${icon(state.repo.partial?'radio':'disc-3')}<span class="eyebrow">${state.repo.partial?'STILL TUNING IN':'YOU’RE ALL CAUGHT UP'}</span><h2>${state.repo.partial?'Some musicians couldn’t load.':'A little room for discovery.'}</h2><p>${state.repo.partial?'Some sources are unavailable. Try again before changing your preferences.':'No more musicians match these preferences right now. Try a wider distance or different instruments.'}</p><button class="primary" data-action="${state.repo.partial?'refresh':'filters'}">${state.repo.partial?'Try again':'Adjust your filters'} ${icon('sliders-horizontal')}</button></div>`}</section><aside class="discovery-aside"><div class="your-sound"><span class="tiny-label">YOUR NEXT COLLABORATION</span><h3>Good chemistry.<br>Great possibilities.</h3><p>Find someone who brings something different to your sound.</p><div class="sound-lines" aria-hidden="true">${Array.from({length:24},(_,i)=>`<i style="height:${12+(i*17%49)}px"></i>`).join('')}</div><div class="aside-divider"></div><span class="tiny-label">YOU’RE LOOKING FOR</span><div class="seeking-list">${(own().seeking||[]).map(x=>`<span>${icon(x==='band'?'users':x==='live'?'radio':'mic-2')}${e(INTENTS[x])}</span>`).join('')||'<span>Creative connections</span>'}</div><button class="text-link" data-action="filters">Fine-tune your search ${icon('arrow-right')}</button></div><div class="tip-card">${icon('headphones')}<div><h4>Let the music speak.</h4><p>A rough rehearsal clip can tell you more than a perfect bio. Give their samples a listen.</p></div></div><button class="small muted privacy-link" data-action="privacy">${icon('shield-check')} A space built on mutual respect</button></aside></div>`}
function sampleCard(s){return s?`<button class="sample-card" data-play="${e(s.media)}" data-type="${e(s.mediaType)}" ${s.sylt?`data-sylt="${e(s.sylt.postUrl)}"`:s.syltDraft?`data-private-clip="${e(s.syltDraft)}"`:""}><span class="sample-play">${icon('play')}</span><span class="sample-title"><strong>${e(s.title||'A little of my sound')}</strong><small>${e(s.contribution||'Performance sample')} · ${Math.round(s.duration||0)} sec</small></span><span class="mini-wave" aria-hidden="true">▂▅▃▇▅▂▆▃▅▂</span></button>${s.sylt?`<button class="quiet" data-open-sylt="${e(s.sylt.postUrl)}">Open in Sylt ↗</button>`:""}`:`<div class="sample-card no-sample"><span class="sample-play">${icon('headphones')}</span><span class="sample-title"><strong>The sound is still coming.</strong><small>No performance samples yet</small></span></div>`}
function connectionsPage(){const cs=matches(),c=cs.find(x=>x.actor===state.chat);return `<section class="page-heading"><div><div class="eyebrow">FROM A GOOD FEELING TO A GREAT SESSION</div><h1>Your connections<span class="accent">.</span></h1><p>A shared interest. A simple hello. See where it goes.</p></div></section><div class="connections-layout"><section class="connection-list"><div class="list-heading">YOUR PEOPLE <span>${cs.length}</span></div>${cs.length?cs.map(c=>{const messages=conversation(state.rows,me(),c),last=messages.at(-1);return `<button class="connection-row ${state.chat===c.actor?'selected':''}" data-chat="${e(c.actor)}">${avatar(c.profile?.value)}<span><strong>${e(c.profile?.value.name||'Musician')}</strong><small>${e(last?.value.text||'You connected. Start a conversation.')}</small></span>${icon('chevron-right')}</button>`}).join(''):`<div class="empty compact">${icon('heart')}<h3>Your people are out there.</h3><p>When you both like each other, you’ll meet here.</p><button class="outline" data-page="discover">Discover musicians</button></div>`}</section><section class="chat-panel">${c?`<header class="chat-header"><button data-view="${e(c.actor)}" class="chat-person">${avatar(c.profile?.value)}<span><strong>${e(nameOf(c.actor))}</strong><small>${list(c.profile?.value.instruments)}</small></span></button><button class="icon-button" data-menu="${e(c.actor)}" aria-label="Connection options">${icon('more-horizontal')}</button></header><div class="chat-messages" id="chat-messages"><div class="chat-start">${icon('audio-lines')}<p>You’re on the same wavelength.</p><span>Try: “What kind of project are you hoping to start?”</span></div>${conversation(state.rows,me(),c).map(o=>`<div class="message ${o.actor===me()?'sent':'received'}"><p>${e(o.value.text)}</p><small>${new Date(o.value.createdAt).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})}${o.actor===me()?icon('check'):''}</small><button class="message-report" data-report="${e(o.actor)}" data-object="${e(o.url)}" aria-label="Report message">${icon('flag')}</button></div>`).join('')}</div><form id="message-form" class="message-form"><label class="sr-only" for="message">Message</label><textarea id="message" name="text" rows="1" maxlength="2000" placeholder="Start something good…" required></textarea><button class="primary icon-button" type="submit" aria-label="Send message">${icon('send')}</button></form><p class="chat-note">Visible to you and this musician. Access-restricted, not end-to-end encrypted.</p>`:`<div class="empty chat-empty">${icon('messages-square')}<span class="eyebrow">MAKE THE FIRST MOVE</span><h2>Every good set<br>starts with a hello.</h2><p>Choose a connection to start talking music.</p></div>`}</section></div>`}
function profilePage(){const p=own();return `<section class="page-heading"><div><div class="eyebrow">THIS IS YOUR SOUND</div><h1>Your musical calling card<span class="accent">.</span></h1><p>A little about you. A reason to make something together.</p></div><button class="primary" data-action="edit">Edit profile ${icon('arrow-up-right')}</button></section><div class="profile-layout"><section class="profile-sheet"><div class="profile-title">${avatar(p,'large')}<div><span class="eyebrow">PUBLIC MUSICIAN PROFILE</span><h2>${e(p.name)}</h2><p>${icon('map-pin')}${e(p.location.city)} · ${list(p.instruments)}</p></div></div><div class="tags">${p.genres.map(g=>`<span>${e(g)}</span>`).join('')}</div><h3>A little about me</h3><p>${e(p.bio||'Your next chapter is waiting to be written.')}</p><h3>On repeat</h3><p>${list(p.inspirations)||'Add the musicians who inspire you.'}</p><h3>Looking for</h3><p>${(p.seeking||[]).map(x=>e(INTENTS[x])).join(' · ')||'Open to connections'}</p><h3>Open to</h3><p>${(p.openTo||[]).map(x=>e(INTENTS[x])).join(' · ')}</p><h3>My sound <span class="muted">${p.samples.length}/3</span></h3>${p.samples.length?p.samples.map(sampleCard).join(''):`<div class="empty compact">${icon('upload')}<h3>Give them something to listen to.</h3><p>A phone recording or rehearsal clip works.</p><button class="outline" data-action="edit">Add a sample</button></div>`}<p class="privacy-caption">${icon('globe')} Your published profile and samples are public through Graffiti.</p></section><aside class="settings-panel"><h3>Your space</h3><button data-action="filters">${icon('sliders-horizontal')} Discovery preferences ${icon('chevron-right')}</button><label class="toggle-row">In-app notifications<input type="checkbox" id="notifications" ${settings().notifications!==false?'checked':''}></label><button data-action="blocked">${icon('ban')} Blocked musicians <span>${blocks(state.rows,me()).length}</span></button><button data-action="privacy">${icon('shield-check')} Privacy & community ${icon('chevron-right')}</button><button data-action="cleanup">${icon('rotate-ccw')} Retry upload cleanup</button><button data-action="logout">${icon('log-out')} Log out</button>${state.repo.moderator===me()?`<button data-action="moderation">${icon('shield-check')} Review reports</button>`:''}<div class="danger-zone"><span class="tiny-label">YOUR DATA, YOUR CHOICE</span><p>Remove your Yudo records and uploads. Your Graffiti account stays yours.</p><button class="danger" data-action="delete">${icon('trash-2')} Remove my app data</button></div>${!moderator&&!state.demo?'<p class="config-note">Pilot setup: a moderator account must be configured before inviting musicians.</p>':''}</aside></div>`}
function modal(title,body,{cleanup=null,wide=false}={}){if(overlays.children.length)closeModal(false);else modalReturn=document.activeElement;modalCleanup=cleanup;overlays.innerHTML=`<div class="backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header><h2 id="modal-title">${e(title)}</h2><button class="icon-button" data-action="close" aria-label="Close dialog">${icon('x')}</button></header>${body}<div class="modal-error" role="alert"></div></section></div>`;app.inert=true;document.body.style.overflow='hidden';paint();overlays.querySelector('input,select,textarea,button')?.focus();}
function closeModal(restore=true){modalCleanup?.();modalCleanup=null;overlays.querySelectorAll('audio,video').forEach(x=>x.pause());overlays.innerHTML='';app.inert=false;document.body.style.overflow='';if(restore&&modalReturn?.isConnected)modalReturn.focus()}
function showProfile(actor){const p=latest(state.rows,'profile',actor)?.value;if(!p){toast('This profile is unavailable.');return}modal(p.name,`<div class="expanded-profile"><div class="profile-title">${avatar(p,'large')}<div><p>${list(p.instruments)}</p><p>${icon('map-pin')}${e(p.location.city)}</p></div></div><div class="tags">${p.genres.map(x=>`<span>${e(x)}</span>`).join('')}</div><h3>A little about me</h3><p>${e(p.bio)}</p><h3>On repeat</h3><p>${list(p.inspirations)}</p><h3>Looking for</h3><p>${p.seeking.map(x=>e(INTENTS[x])).join(' · ')||'Creative connections'}</p><h3>Open to</h3><p>${p.openTo.map(x=>e(INTENTS[x])).join(' · ')}</p>${p.statement?`<p>${e(p.statement)}</p>`:''}<h3>Their sound</h3>${p.samples.length?p.samples.map(sampleCard).join(''):'<p class="muted">No performance samples yet.</p>'}<div class="actions">${matches().some(c=>c.actor===actor)?`<button class="primary" data-chat="${e(actor)}">Send a message ${icon('send')}</button>`:`<button class="outline" data-pass="${e(actor)}">${icon('x')} Pass</button><button class="primary" data-like="${e(actor)}">${icon('heart')} Connect</button>`}<button class="quiet" data-menu="${e(actor)}">Options ${icon('more-horizontal')}</button></div></div>`,{wide:true})}
function menu(actor){modal('Your connection, your choice',`<p>Manage your interaction with ${e(nameOf(actor))}.</p><div class="menu-actions">${matches().some(c=>c.actor===actor)?`<button data-unmatch="${e(actor)}">${icon('x')} Unmatch</button>`:''}<button data-report="${e(actor)}">${icon('flag')} Report musician</button><button class="danger" data-block="${e(actor)}">${icon('ban')} Block musician</button></div><p class="small muted">Blocking hides this musician and their interactions in Yudo. Public profiles remain accessible outside this app.</p>`)}
function filterModal(){const s=settings();modal('Fine-tune your search',`<form id="filter-form"><label for="radius">Distance <span id="radius-label">${s.radius||25} miles</span></label><input id="radius" name="radius" type="range" min="5" max="250" step="5" value="${s.radius||25}"><p class="small muted">Approximate distance from ${e(own().location.city)}. We won’t expand it without asking.</p><label>Instruments <small>Leave empty for any instrument</small></label>${checks('instruments',INSTRUMENTS,s.instruments)}<label>Genres <small>Leave empty for all genres</small></label>${checks('genres',GENRES,s.genres)}<label for="intent">Opportunity</label><select id="intent" name="intent"><option value="">All opportunities</option>${Object.entries(INTENTS).map(([k,v])=>`<option value="${k}" ${s.intent===k?'selected':''}>${v}</option>`).join('')}</select><div class="actions"><button class="quiet" type="button" data-action="reset-filters">Reset filters</button><button class="primary" type="submit">Apply filters ${icon('check')}</button></div></form>`)}
function checks(name,options,selected=[]){return `<div class="chip-options">${options.map(x=>{const value=Array.isArray(x)?x[0]:x,label=Array.isArray(x)?x[1]:x;return `<label class="choice"><input type="checkbox" name="${name}" value="${e(value)}" ${selected?.includes(value)?'checked':''}><span>${e(label)}</span></label>`}).join('')}</div>`}
let draft=null;
function getDraft(){return structuredClone(latest(state.rows,'draft',me())?.value||own()||{name:'',bio:'',avatar:'',location:{city:'',lat:null,lng:null},instruments:[],genres:[],inspirations:[],samples:[],seeking:[],openTo:[],statement:''})}
const steps=['Introduction','Location','Your music','Your sound','Connections','Publish'];
function onboarding(){draft??=getDraft();const d=draft,step=state.step;
 const form=step===0?`<div class="eyebrow">NICE TO MEET YOU</div><h1>Let’s start with you<span class="accent">.</span></h1><p>The person behind the sound.</p>${workspace?`<button type="button" class="outline" data-action="import-sylt">Import profile details from Sylt</button>`:""}<label for="name">Display name</label><input id="name" name="name" value="${e(d.name)}" maxlength="60" placeholder="What should we call you?" required><label for="avatar">Profile image <small>Optional · up to 10 MB</small></label><input id="avatar" name="avatar" type="file" accept="image/jpeg,image/png,image/webp">${d.avatar?`<div class="avatar-preview">${avatar(d,'large')}<button type="button" class="quiet" data-action="remove-avatar">Remove image</button></div>`:''}<label for="bio">A little about you <small>Optional</small></label><textarea id="bio" name="bio" rows="4" maxlength="700" placeholder="What do you play, and what would you love to make?">${e(d.bio)}</textarea>`:
 step===1?`<div class="eyebrow">GOOD MUSIC HAPPENS NEARBY</div><h1>Where’s your scene<span class="accent">?</span></h1><p>We only publish your city and a coarse location.</p><label for="city">City</label><input list="cities" id="city" name="city" value="${e(d.location.city)}" placeholder="Search or enter a city" required><datalist id="cities">${CITIES.map(c=>`<option value="${e(c[0])}"></option>`).join('')}</datalist><div class="actions city-actions"><button class="outline" type="button" data-action="lookup-city">${icon('globe')} Find city</button><button class="outline" type="button" data-action="locate">${icon('map-pin')} Use current location</button></div><div id="city-results" role="status"></div><p class="small muted">Choose a suggestion or find your city. City searches use <a href="https://open-meteo.com/" target="_blank" rel="noopener noreferrer">Open-Meteo</a> and GeoNames; device coordinates stay in your browser until rounded.</p><input id="lat" name="lat" type="hidden" value="${d.location.lat??''}"><input id="lng" name="lng" type="hidden" value="${d.location.lng??''}"><label for="radius">Discovery distance</label><select id="radius" name="radius">${[10,25,50,100,250].map(x=>`<option ${x===(d.settings?.radius||settings().radius)?'selected':''}>${x}</option>`).join('')}</select><p class="small muted">Miles from your approximate location. Change this any time.</p>`:
 step===2?`<div class="eyebrow">TELL US WHAT MOVES YOU</div><h1>What’s your sound<span class="accent">?</span></h1><p>Self-taught, classically trained, somewhere in between. You belong here.</p><label for="primary">Primary instrument or role</label><select id="primary" name="primary" required><option value="">Choose your role</option>${INSTRUMENTS.map(x=>`<option ${d.instruments[0]===x?'selected':''}>${e(x)}</option>`).join('')}</select><label>Other instruments</label>${checks('instruments',INSTRUMENTS,d.instruments.slice(1))}<label>Your genres</label>${checks('genres',GENRES,[...d.genres])}<label for="inspirations">Musical inspirations <small>Separate with commas</small></label><input id="inspirations" name="inspirations" list="inspiration-options" value="${e(d.inspirations.join(', '))}" maxlength="400" placeholder="Khruangbin, Radiohead, Erykah Badu…"><datalist id="inspiration-options">${['Khruangbin','Radiohead','Erykah Badu','Anderson .Paak','Vulfpeck','Hiatus Kaiyote','Nubya Garcia'].map(x=>`<option>${x}</option>`).join('')}</datalist>`:
 step===3?`<div class="eyebrow">LET THE MUSIC SPEAK</div><h1>A little of your sound<span class="accent">.</span></h1><p>A rehearsal clip or phone recording works. You can also add this later.</p>${workspace?`<div class="actions"><button type="button" class="outline" data-action="add-sylt">Add from Sylt</button><button type="button" class="quiet" data-action="manage-sylt">Manage public Sylt excerpts</button></div>`:""}<div class="upload-zone">${icon('upload')}<h3>No perfect takes required.</h3><p>Audio or video · 60 sec max · 50 MB max</p><label for="sample" class="outline">Choose a sample</label><input id="sample" type="file" accept="audio/mpeg,audio/mp4,audio/wav,audio/x-wav,audio/x-m4a,video/mp4,video/webm" ${d.samples.length>=3?'disabled':''}><small>MP3, M4A, WAV, MP4, WebM · ${d.samples.length}/3</small></div><div id="upload-status" role="status"></div>${d.samples.map((s,i)=>`<div class="draft-sample">${sampleCard(s)}<label>Title<input name="title-${i}" value="${e(s.title)}" maxlength="100"></label><label>Your contribution<input name="contribution-${i}" value="${e(s.contribution)}" maxlength="100" placeholder="e.g. Drums"></label><div class="actions"><label class="inline-choice"><input type="radio" name="featured" value="${i}" ${i===0?'checked':''}> Featured sample</label><button type="button" class="quiet" data-move-sample="${i}" ${i===0?"disabled":""}>Move earlier</button><button type="button" class="quiet danger" data-remove-sample="${i}">Remove</button></div></div>`).join('')}`:
 step===4?`<div class="eyebrow">MAKE ROOM FOR SOMETHING GOOD</div><h1>Who’s missing from<br>your sound<span class="accent">?</span></h1><p>Tell us what you need and where you’d like to take your music.</p><label>I’m looking for</label>${checks('seeking',[['band','People to form a band'],['live','Live musicians'],['session','Session musicians']],d.seeking)}<label>I’m open to</label>${checks('openTo',[['band','Forming or joining a band'],['live','Playing live'],['session','Recording sessions']],d.openTo)}<label>Instruments I’m seeking <small>Leave empty for any instrument</small></label>${checks('wanted',INSTRUMENTS,d.settings?.instruments||settings().instruments)}<label for="statement">A little more about your plans <small>Optional</small></label><textarea id="statement" name="statement" rows="3" maxlength="400" placeholder="Looking for a drummer and bassist to start a shoegaze project…">${e(d.statement)}</textarea>`:
 `<div class="eyebrow">READY FOR YOUR NEXT CHAPTER?</div><h1>Put your sound out there<span class="accent">.</span></h1><p>One last look before the first hello.</p><div class="review-card"><div class="profile-title">${avatar(d,'large')}<div><h2>${e(d.name)}</h2><p>${list(d.instruments)} · ${e(d.location.city)}</p></div></div><div class="tags">${d.genres.map(x=>`<span>${e(x)}</span>`).join('')}</div><p>${e(d.bio)}</p><p><strong>Looking for:</strong> ${d.seeking.map(x=>e(INTENTS[x])).join(' · ')||'Creative connections'}</p><p><strong>Open to:</strong> ${d.openTo.map(x=>e(INTENTS[x])).join(' · ')}</p><p>${d.samples.length} sample${d.samples.length===1?'':'s'} · Within ${d.settings?.radius||25} miles</p></div>${d.samples.some(s=>s.sylt||s.syltDraft)?`<div class="consent-box"><p>Only the selected Sylt clips will become public on your Yudo profile. Your original Sylt recordings keep their current visibility.</p></div>`:""}<div class="consent-box">${icon('globe')}<p>Your profile, approximate location, and published samples will be public through Graffiti and may be accessible outside this app. Your discovery settings, passes, likes, and conversations will have restricted access.</p></div><label class="inline-choice"><input type="checkbox" name="consent" required> I’m 18 or older and agree to publish this profile.</label>`;
 app.innerHTML=`<div class="onboarding"><header><a class="brand" href="/">${brand()}</a><button class="quiet" data-action="${own()?'cancel-edit':'logout'}">${own()?'Save draft & exit':'Log out'} ${icon('x')}</button></header>${state.demo?'<div class="demo-banner">Demo only · this profile stays in your browser</div>':''}<div class="onboard-layout"><aside><span class="eyebrow">YOUR MUSICIAN PROFILE</span><h2>Every great band<br>starts somewhere.</h2><ol>${steps.map((s,i)=>`<li class="${i===step?'current':i<step?'done':''}"><span>${i<step?icon('check'):i+1}</span>${s}</li>`).join('')}</ol><p>${icon('shield-check')} Your draft stays private until you publish.</p></aside><form id="onboard-form" class="onboard-form">${form}<div id="onboard-error" class="error hidden" role="alert"></div><footer><button type="button" class="quiet" data-action="back" ${step===0?'disabled':''}>${icon('chevron-left')} Back</button><span>STEP ${step+1} OF 6</span><button type="submit" class="primary">${step===5?'Publish & discover':'Save & continue'} ${icon('arrow-right')}</button></footer></form></div></div>`;paint();}
function readStep(form){const fd=new FormData(form);if(state.step===0){draft.name=String(fd.get('name')).trim();draft.bio=String(fd.get('bio')).trim();if(!draft.name)throw Error('Add a display name.');}
 if(state.step===1){const city=String(fd.get('city')).trim(),known=CITIES.find(x=>x[0].toLowerCase()===city.toLowerCase());const lat=known?.[1]??(fd.get('lat')!==''?Number(fd.get('lat')):NaN),lng=known?.[2]??(fd.get('lng')!==''?Number(fd.get('lng')):NaN);if(!city||!Number.isFinite(lat)||!Number.isFinite(lng)||Math.abs(lat)>90||Math.abs(lng)>180)throw Error('Choose a suggested city, find your city, or use current location.');draft.location={city,...coarse(lat,lng)};draft.settings={...settings(),...draft.settings,radius:Number(fd.get('radius'))};}
 if(state.step===2){const primary=String(fd.get('primary'));if(!primary)throw Error('Choose your primary instrument.');draft.instruments=[...new Set([primary,...fd.getAll('instruments')])];draft.genres=fd.getAll('genres');if(!draft.genres.length)throw Error('Choose at least one genre.');draft.inspirations=String(fd.get('inspirations')).split(',').map(x=>x.trim()).filter(Boolean).slice(0,12);}
 if(state.step===3){draft.samples=draft.samples.map((s,i)=>({...s,title:String(fd.get(`title-${i}`)||s.title),contribution:String(fd.get(`contribution-${i}`)||s.contribution)}));const i=Number(fd.get('featured')||0);if(i>0)draft.samples.unshift(...draft.samples.splice(i,1));}
 if(state.step===4){draft.seeking=fd.getAll('seeking');draft.openTo=fd.getAll('openTo');draft.statement=String(fd.get('statement')).trim();if(!draft.seeking.length&&!draft.openTo.length)throw Error('Choose what you’re seeking or open to.');draft.settings={...settings(),...draft.settings,instruments:fd.getAll('wanted')};}
 if(state.step===5&&!fd.get('consent'))throw Error('Please confirm the public publishing notice.');}
async function saveDraft(){await state.repo.replace('draft',{...draft,step:state.step});state.rows=state.repo.rows;}
async function startSession(session,demo=false){const id=++epoch;clearInterval(timer);closeModal(false);clearMedia();draft=null;state.session=session;state.demo=demo;state.loading=true;state.error='';state.page='discover';state.chat=null;state.editing=false;state.rows=[];pendingOps.clear();state.restoring=false;render();const api=demo?new DemoAPI():graff;try{if(demo)await seed(api,Repository);if(id!==epoch)return;const repo=new Repository(api,session,{moderator:demo?'demo:moderator':moderator});state.repo=repo;await repo.refresh({full:true});if(id!==epoch)return;state.rows=repo.rows;state.step=latest(state.rows,'draft',me())?.value.step||0;state.loading=false;render();timer=setInterval(()=>refresh(false),7000);}catch(err){if(id!==epoch)return;state.error=err.message;state.loading=false;render();}}
function endSession(){++epoch;clearInterval(timer);state.repo=null;state.session=null;state.rows=[];state.chat=null;state.error='';state.restoring=false;draft=null;pendingOps.clear();clearMedia();closeModal(false);render()}
async function refresh(show=true){if(!state.repo||refreshing)return;refreshing=true;const id=epoch,repo=state.repo,old=matches().map(x=>x.id),oldMessages=state.rows.filter(o=>o.value.type==='message').map(o=>o.url);try{await repo.refresh();if(id!==epoch)return;state.rows=repo.rows;state.error=repo.partial?'Some sources are unavailable. Your loaded connections are still here.':'';const next=matches().find(c=>!old.includes(c.id));if(next&&settings().notifications!==false)toast(`You and ${nameOf(next.actor)} connected.`);const incoming=state.rows.find(o=>o.value.type==='message'&&o.actor!==me()&&!oldMessages.includes(o.url)&&matches().some(c=>conversation(state.rows,me(),c).includes(o)));if(incoming&&settings().notifications!==false)toast(`New message from ${nameOf(incoming.actor)}`);if(show||(!draft&&!overlays.children.length&&document.activeElement?.id!=='message'))render();}catch(err){if(id===epoch){state.error=err.message;if(show)render();else toast('Couldn’t refresh. Your existing data is still here.')}}finally{refreshing=false}}
async function operation(key,type,data){let op=pendingOps.get(key);if(!op){op={id:crypto.randomUUID(),data,type};pendingOps.set(key,op);const result=await state.repo.write(type,data,op.id);pendingOps.delete(key);return result}const result=await state.repo.retryWrite(op.type,op.data,op.id);pendingOps.delete(key);return result}
async function like(actor){if(blocks(state.rows,me()).includes(actor))throw Error('Unblock this musician before connecting.');await operation(`like:${actor}`,'like',{target:actor});state.rows=state.repo.rows;closeModal();const c=matches().find(x=>x.actor===actor);render();if(c)modal('You’re on the same wavelength.',`<div class="match-celebration">${icon('audio-lines')}<h3>You and ${e(nameOf(actor))} connected.</h3><p>A good sound starts with a conversation.</p><button class="primary full" data-chat="${e(actor)}">Send a message ${icon('send')}</button><button class="quiet full" data-action="close">Keep discovering</button></div>`);else toast('Interest sent. You’ll connect when they like you back.');}
async function unmatch(actor){const c=matches().find(x=>x.actor===actor);if(c){await operation(`close:${c.id}`,'closure',{target:actor,likes:c.likes});await operation(`unlike:${actor}`,'like',{target:actor,active:false});}state.rows=state.repo.rows;state.chat=null;}
async function openPlayer(url,type){modal('Hear their sound',`<p class="muted">Loading sample…</p>`);try{const src=await mediaURL(url);if(!overlays.children.length)return;modal('Hear their sound',`${type.startsWith('video')?`<video controls playsinline src="${e(src)}"></video>`:`<div class="player-art">${icon('audio-lines')}</div><audio controls src="${e(src)}"></audio>`}<p class="small muted">Press play when you’re ready.</p>`);overlays.querySelector('audio,video').addEventListener('error',()=>{overlays.querySelector('.modal-error').textContent='This sample can’t be played in this browser. Try another sample.'})}catch(err){overlays.querySelector('.modal-error').textContent='This sample is unavailable. It may have been removed.';}}
function loadChatScroll(){const el=document.querySelector('#chat-messages');if(el)el.scrollTop=el.scrollHeight;}
document.addEventListener('click',async event=>{const b=event.target.closest('button,a[data-action]');if(!b)return;if(b.dataset.action==='login'){state.error='';try{await graff.login()}catch(err){state.error=err.message;render()}return}if(actionBusy)return;
 if(b.dataset.page){closeModal();state.page=b.dataset.page;render();return}if(b.dataset.openSylt){if(workspace)workspace.navigate('sylt',`?excerpt=${encodeURIComponent(b.dataset.openSylt)}`);else window.location.href=`/sylt/?excerpt=${encodeURIComponent(b.dataset.openSylt)}`;return}if(b.dataset.view){showProfile(b.dataset.view);return}if(b.dataset.menu){menu(b.dataset.menu);return}if(b.dataset.play){if(b.dataset.sylt){const profile=state.rows.find(o=>o.value.type==='profile'&&o.value.samples?.some(s=>s.sylt?.postUrl===b.dataset.sylt));try{const resolved=await state.repo.sylt.resolve(b.dataset.sylt,profile?.actor||me());const video=document.createElement(b.dataset.type.startsWith('video')?'video':'audio');video.src=URL.createObjectURL(resolved.blob);video.preload='metadata';await new Promise((resolve,reject)=>{video.onloadedmetadata=()=>video.duration<=60?resolve():reject(Error('This excerpt exceeds 60 seconds.'));video.onerror=()=>reject(Error('Excerpt cannot be played.'))});const src=video.src;modal('A moment from Sylt',`<${b.dataset.type.startsWith('video')?'video':'audio'} controls src="${e(src)}"></${b.dataset.type.startsWith('video')?'video':'audio'}><p>Featured from Sylt</p>`,{cleanup:()=>URL.revokeObjectURL(src)});}catch(err){modal('Sylt excerpt unavailable',`<p>${e(err.message)} Retry after refreshing the profile. The owner may have removed this excerpt.</p>`)}return;}if(b.dataset.privateClip&&workspace){const r=await graff.get(b.dataset.privateClip,{},state.session);const media=await graff.getMedia(r.value.media,{types:['audio/*','video/*'],maxBytes:50*1024*1024},state.session);const src=URL.createObjectURL(media.data);modal('Private Sylt clip',`<${b.dataset.type.startsWith('video')?'video':'audio'} controls src="${src}"></${b.dataset.type.startsWith('video')?'video':'audio'}>`,{cleanup:()=>URL.revokeObjectURL(src)});return;}await openPlayer(b.dataset.play,b.dataset.type);return}if(b.dataset.chat){closeModal();state.chat=b.dataset.chat;state.page='connections';render();return}
 actionBusy=true;b.disabled=true;try{
  if(b.dataset.cityResult){const c=JSON.parse(b.dataset.cityResult);draft.location=c;document.querySelector('#city').value=c.city;document.querySelector('#lat').value=c.lat;document.querySelector('#lng').value=c.lng;document.querySelector('#city-results').textContent='City selected.';}
  if(b.dataset.exclude){await state.repo.write('exclusion',{target:b.dataset.exclude,active:true});state.rows=state.repo.rows;toast('Musician excluded from Yudo discovery.');closeModal();render();}
  if(b.dataset.deleteExcerpt){await workspace.crosspost().removeExcerpt(b.dataset.deleteExcerpt);closeModal();toast('Public Sylt excerpt removed.');}
  if(b.dataset.like)await like(b.dataset.like);
  if(b.dataset.pass){await operation(`pass:${b.dataset.pass}`,'pass',{target:b.dataset.pass});state.rows=state.repo.rows;closeModal();render();}
  if(b.dataset.unmatch){await unmatch(b.dataset.unmatch);closeModal();render();toast('Connection closed.');}
  if(b.dataset.block){const actor=b.dataset.block;await unmatch(actor);await operation(`block:${actor}`,'block',{target:actor,active:true});state.rows=state.repo.rows;closeModal();render();toast('Musician blocked in Yudo.');}
  if(b.dataset.unblock){await state.repo.write('block',{target:b.dataset.unblock,active:false});state.rows=state.repo.rows;closeModal();render();toast('Musician unblocked. Earlier connections remain closed.');}
  if(b.dataset.report){modal('Report an interaction',`<form id="report-form"><input type="hidden" name="target" value="${e(b.dataset.report)}"><input type="hidden" name="object" value="${e(b.dataset.object||latest(state.rows,'profile',b.dataset.report)?.url||'')}"><p>Reports are shared only with you and the configured moderator.</p><label for="reason">Reason</label><select id="reason" name="reason"><option>Harassment or hate</option><option>Spam or impersonation</option><option>Inappropriate media</option><option>Other concern</option></select><label for="details">What happened?</label><textarea id="details" name="details" rows="4" maxlength="1500" required></textarea>${!state.repo.moderator?'<p class="error">Reporting is not configured. Contact the app owner before using this pilot with others.</p>':''}<button class="primary" type="submit" ${!state.repo.moderator?'disabled':''}>Submit report ${icon('flag')}</button></form>`);}
  if(b.dataset.moveSample!==undefined){readStep(document.querySelector('#onboard-form'));const index=Number(b.dataset.moveSample);if(index>0)[draft.samples[index-1],draft.samples[index]]=[draft.samples[index],draft.samples[index-1]];await saveDraft();render();}
  if(b.dataset.removeSample!==undefined){readStep(document.querySelector('#onboard-form'));const index=Number(b.dataset.removeSample);draft.samples.splice(index,1);await saveDraft();render();}
  switch(b.dataset.action){
   case 'demo':sessionStorage.setItem('soundcheck-demo','1');await startSession({actor:'demo:alex'},true);break;
   case 'logout':if(state.demo){sessionStorage.removeItem('soundcheck-demo');endSession()}else await graff.logout(state.session);break;
   case 'close':closeModal();break;
   case 'filters':filterModal();break;
   case 'refresh':await refresh();break;
   case 'reload-session':await startSession(state.session,state.demo);break;
   case 'reset-filters':await state.repo.replace('settings',{...settings(),radius:25,instruments:[],genres:[],intent:''});state.rows=state.repo.rows;filterModal();render();break;
   case 'add-sylt':{readStep(document.querySelector('#onboard-form'));if(draft.samples.length>=3)throw Error('You can feature up to three samples in total.');const sample=await workspace.selectClip();if(sample){draft.samples.push(sample);await saveDraft();render()}break;}
   case 'retry-sylt-cleanup':await workspace.crosspost().retryCleanup();toast('Sylt cleanup complete.');break;
   case 'manage-sylt':{const service=workspace.crosspost(),excerpts=await service.excerpts();modal('Public Sylt excerpts',`<p>Removing a sample from Yudo does not delete its public Sylt version. You can remove public versions here.</p>${excerpts.map(o=>`<div class="blocked-row"><span>${e(o.value.title)}</span><button data-delete-excerpt="${e(o.url)}">Remove public excerpt</button></div>`).join('')||'<p>No public excerpts.</p>'}<button class="outline" data-action="retry-sylt-cleanup">Retry excerpt cleanup</button>`);break;}
   case 'import-sylt':{const records=await workspace.crosspost().list();const p=records.filter(o=>o.actor===me()&&o.value.type==='profile').sort((a,b)=>b.value.createdAt-a.value.createdAt)[0]?.value;if(!p)throw Error('Create a Sylt profile first.');modal('Import profile details from Sylt',`<p>Choose fields to copy into your private Yudo draft. Later edits stay independent.</p><form id="import-sylt-form"><label class="inline-choice"><input type="checkbox" name="name" checked>Name: ${e(p.name)}</label><label class="inline-choice"><input type="checkbox" name="avatar">Image: ${e(p.avatar||'No image')}</label><label class="inline-choice"><input type="checkbox" name="instrument" checked>Instrument: ${e(p.instrument||'Choose below')}</label><label for="import-role">Map instrument to Yudo role</label><select id="import-role" name="role"><option value="">Choose matching role</option>${INSTRUMENTS.map(x=>`<option ${x.toLowerCase()===(p.instrument||'').toLowerCase()?'selected':''}>${e(x)}</option>`).join('')}</select><input type="hidden" name="profile" value="${e(JSON.stringify(p))}"><button type="submit" class="primary">Import selected fields</button></form>`);break;}
   case 'edit':draft=getDraft();state.step=0;state.editing=true;render();break;
   case 'back':if(state.step>0){state.step--;await saveDraft();render()}break;
   case 'cancel-edit':if(state.step<5)readStep(document.querySelector('#onboard-form'));await saveDraft();draft=null;state.editing=false;render();break;
   case 'remove-avatar':draft.avatar='';await saveDraft();render();break;
   case 'lookup-city':{const city=document.querySelector('#city').value.trim();if(city.length<2)throw Error('Enter a city name first.');const response=await fetch(`https://geocoding-api.open-meteo.com/v1/search?name=${encodeURIComponent(city)}&count=5&language=en&format=json`,{signal:AbortSignal.timeout(10000)});if(!response.ok)throw Error('City search is unavailable. Try a suggestion or current location.');const result=await response.json();const holder=document.querySelector('#city-results');holder.innerHTML=result.results?.length?result.results.map(c=>{const location={city:[c.name,c.admin1,c.country_code].filter(Boolean).join(', '),...coarse(c.latitude,c.longitude)};return `<button type="button" class="city-result" data-city-result="${e(JSON.stringify(location))}">${icon('map-pin')}${e(location.city)}</button>`}).join(''):'No cities found. Try a nearby city or current location.';break;}
   case 'locate':{if(!navigator.geolocation)throw Error('Location is unavailable. Choose a city instead.');const position=await new Promise((res,rej)=>navigator.geolocation.getCurrentPosition(res,rej,{enableHighAccuracy:false,timeout:12000,maximumAge:300000}));const c=coarse(position.coords.latitude,position.coords.longitude);draft.location={...draft.location,...c};document.querySelector('#lat').value=c.lat;document.querySelector('#lng').value=c.lng;draft.deviceLocation=true;toast('Approximate location set. Add your city name to continue.');break;}
   case 'privacy':modal('Your space, your choice',`<div class="privacy-content"><h3>Music first. Mutual respect, always.</h3><p>Share performances you have permission to use. Be honest about your role and kind when reaching out. Harassment, impersonation, and spam don’t belong here.</p><h3>What’s public?</h3><p>Your published profile, city, approximate location, image, and samples are public through Graffiti. They may be accessible outside Yudo.</p><h3>What has restricted access?</h3><p>Your drafts, settings, passes, and blocks are private to your account. Likes and messages are shared with the other participant. Reports go to the moderator. Access restrictions are not end-to-end encryption.</p><h3>Your controls</h3><p>Unmatch to end a connection. Block to hide someone in this app. These controls cannot retract copies already received or prevent someone viewing public data elsewhere.</p><p>You can remove your authored app data in Profile. Your Graffiti identity and other people’s records are separate.</p></div>`);break;
   case 'moderation':{if(state.repo.moderator!==me())throw Error('Moderator access required.');const reports=state.rows.filter(o=>o.value.type==='report');modal('Review reports',reports.length?reports.map(o=>`<div class="report-item"><h3>${e(o.value.reason)}</h3><p>${e(o.value.details)}</p><p class="small muted">Reporter: ${e(o.actor)}<br>Target: ${e(o.value.target)}<br>Reference: ${e(o.value.object)}</p><button class="outline danger" data-exclude="${e(o.value.target)}">Exclude from discovery</button></div>`).join(''):'<p>No reports to review.</p>');break;}
   case 'blocked':modal('Blocked musicians',`${blocks(state.rows,me()).map(a=>`<div class="blocked-row"><span>${e(nameOf(a))}</span><button class="outline" data-unblock="${e(a)}">Unblock</button></div>`).join('')||'<p>No blocked musicians.</p>'}`);break;
   case 'cleanup':{const failures=await state.repo.cleanup();state.rows=state.repo.rows;toast(failures.length?'Some uploads still couldn’t be removed. Try again when connected.':'Upload cleanup complete.');break;}
   case 'delete':modal('Remove your Yudo data?',`<p>This removes your authored Yudo records and uploaded media. It doesn’t delete your Graffiti account, other people’s messages, or copies already received.</p><p>If a source is unavailable, you can retry incomplete removal.</p><form id="delete-form"><label class="inline-choice"><input type="checkbox" name="confirm" required> I understand and want to remove my app data.</label><button class="primary danger-fill" type="submit">Remove my app data ${icon('trash-2')}</button></form>`);break;
  }
 }catch(err){const target=overlays.querySelector('.modal-error')||document.querySelector('#onboard-error');if(target){target.classList.remove('hidden');target.textContent=err.message}else toast(err.message)}finally{actionBusy=false;if(b.isConnected)b.disabled=false;paint();}});
document.addEventListener('submit',async event=>{event.preventDefault();if(actionBusy)return;const form=event.target,button=form.querySelector('button[type="submit"]'),fd=new FormData(form),id=epoch;actionBusy=true;if(button){button.disabled=true;button.dataset.original=button.innerHTML;button.textContent='Saving…';}
try{
 if(form.id==='onboard-form'){readStep(form);if(state.step<5){const previous=state.step;state.step++;try{await saveDraft()}catch(err){state.step=previous;throw err}render()}else{validateProfile(draft);let op=pendingOps.get('publish');if(!op){op={id:latest(state.rows,'draft',me())?.value.publish?.operationId||crypto.randomUUID()};pendingOps.set('publish',op)}else await state.repo.refresh({full:true});const {settings:ds,publish,step,deviceLocation,...p}=draft;await state.repo.publish(p,{...settings(),...ds},op.id);if(id!==epoch)return;pendingOps.delete('publish');state.rows=state.repo.rows;draft=null;state.editing=false;render();toast(state.repo.warning||'Your profile is live. Let’s find your people.');}}
 if(form.id==='import-sylt-form'){const p=JSON.parse(fd.get('profile'));draft.name=document.querySelector('#name')?.value||draft.name;draft.bio=document.querySelector('#bio')?.value||draft.bio;if(fd.get('name'))draft.name=p.name;if(fd.get('instrument')&&!fd.get('role'))throw Error('Choose the Yudo role that matches your Sylt instrument.');if(fd.get('instrument'))draft.instruments=[String(fd.get('role')),...draft.instruments.filter(x=>x!==String(fd.get('role')))];if(fd.get('avatar')&&p.avatar){if(!/^https:\/\//.test(p.avatar))throw Error('The Sylt profile image must use HTTPS.');const response=await fetch(p.avatar,{referrerPolicy:'no-referrer'});const blob=await response.blob();if(!response.ok||!['image/jpeg','image/png','image/webp'].includes(blob.type)||blob.size>10*1024*1024)throw Error('This profile image cannot be imported.');draft.avatar=await state.repo.upload(blob);}await saveDraft();closeModal();render();}
 if(form.id==='filter-form'){await state.repo.replace('settings',{...settings(),radius:Number(fd.get('radius')),instruments:fd.getAll('instruments'),genres:fd.getAll('genres'),intent:String(fd.get('intent'))});state.rows=state.repo.rows;closeModal();render();}
 if(form.id==='message-form'){const text=String(fd.get('text')).trim(),c=matches().find(x=>x.actor===state.chat);if(!c)throw Error('This connection is no longer available.');await operation(`message:${c.id}:${text}`,'message',{target:c.actor,likes:c.likes,text});state.rows=state.repo.rows;render();toast('Message sent.');}
 if(form.id==='report-form'){await operation(`report:${fd.get('object')}`,'report',{target:String(fd.get('target')),object:String(fd.get('object')),reason:String(fd.get('reason')),details:String(fd.get('details'))});state.rows=state.repo.rows;closeModal();toast(state.demo?'Demo report saved locally. No moderator was contacted.':'Report submitted to the moderator.');}
 if(form.id==='delete-form'){if(!fd.get('confirm'))throw Error('Confirm removal first.');const failures=await state.repo.removeAll();state.rows=state.repo.rows;if(failures.length)throw Error(`${failures.length} item(s) couldn’t be removed. Stay signed in and submit again to retry.`);draft=null;state.step=0;state.editing=false;closeModal();render();toast('Your Yudo data was removed. Your Graffiti account is unchanged.');}
}catch(err){if(id!==epoch)return;const target=overlays.querySelector('.modal-error')||document.querySelector('#onboard-error');if(target){target.classList.remove('hidden');target.textContent=err.message}else toast(`${err.message} Your text is still here; send again to retry.`)}finally{actionBusy=false;if(button?.isConnected){button.disabled=false;button.innerHTML=button.dataset.original}paint()}});
async function fileDuration(file){const el=document.createElement(file.type.startsWith('video')?'video':'audio'),url=URL.createObjectURL(file);return new Promise((resolve,reject)=>{const finish=(fn,v)=>{el.removeAttribute('src');el.load();URL.revokeObjectURL(url);clearTimeout(timeout);fn(v)};const timeout=setTimeout(()=>finish(reject,Error('Couldn’t read this recording. Try another file.')),15000);el.onloadedmetadata=()=>finish(resolve,el.duration);el.onerror=()=>finish(reject,Error('This recording cannot be played in this browser.'));el.preload='metadata';el.src=url})}
document.addEventListener('change',async event=>{const el=event.target;if(el.id==='notifications'){try{await state.repo.replace('settings',{...settings(),notifications:el.checked});state.rows=state.repo.rows;toast('Notification preference saved.')}catch(err){el.checked=!el.checked;toast(err.message)}return}if(el.id==='city'){const c=CITIES.find(c=>c[0].toLowerCase()===el.value.toLowerCase());if(c){document.querySelector('#lat').value=c[1];document.querySelector('#lng').value=c[2]}else if(!draft?.deviceLocation&&el.value!==draft?.location.city){document.querySelector('#lat').value='';document.querySelector('#lng').value=''}return}if(!['sample','avatar'].includes(el.id)||!el.files?.[0])return;if(actionBusy)return;actionBusy=true;const file=el.files[0],id=epoch;const buttons=document.querySelectorAll('#onboard-form button');buttons.forEach(b=>b.disabled=true);const status=document.querySelector('#upload-status');if(status)status.textContent='Checking your recording…';
 try{if(el.id==='avatar'){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024)throw Error('Choose a JPG, PNG, or WebP image under 10 MB.');draft.name=document.querySelector('#name').value;draft.bio=document.querySelector('#bio').value;draft.avatar=await state.repo.upload(file);}
 else{readStep(document.querySelector('#onboard-form'));if(draft.samples.length>=3)throw Error('You can add up to three samples.');if(file.size>MAX_BYTES)throw Error('Samples must be 50 MB or smaller.');const duration=await fileDuration(file);validateMedia(file,duration);if(status)status.textContent='Uploading privately…';const media=await state.repo.upload(file);draft.samples.push({media,mediaType:file.type,duration,title:file.name.replace(/\.[^.]+$/,''),contribution:draft.instruments[0]||''});}if(id!==epoch)return;await saveDraft();render();toast('Uploaded privately. It becomes public only when you publish.');}catch(err){if(status)status.textContent=`${err.message} Choose the file again to retry.`;else toast(err.message)}finally{actionBusy=false;buttons.forEach(b=>b.disabled=false);el.value='';}});
document.addEventListener('input',event=>{if(event.target.id==='radius'){const label=document.querySelector('#radius-label');if(label)label.textContent=`${event.target.value} miles`}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&overlays.children.length&&!actionBusy)closeModal();if(event.key==='Tab'&&overlays.children.length){const els=[...overlays.querySelectorAll('button,input,textarea,select,a[href],audio,video')].filter(el=>!el.disabled&&el.offsetParent!==null),first=els[0],last=els.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus()}}});
let swipeStart=null;document.addEventListener('pointerdown',ev=>{const card=ev.target.closest('#swipe-card');if(card&&!ev.target.closest('button,audio,video'))swipeStart={x:ev.clientX,y:ev.clientY,actor:card.dataset.actor}});document.addEventListener('pointerup',ev=>{if(!swipeStart)return;const start=swipeStart;swipeStart=null;const dx=ev.clientX-start.x,dy=ev.clientY-start.y;if(Math.abs(dx)>100&&Math.abs(dx)>Math.abs(dy)*1.5){const btn=document.querySelector(`[data-${dx>0?'like':'pass'}="${CSS.escape(start.actor)}"]`);btn?.click()}});document.addEventListener('pointercancel',()=>swipeStart=null);
