window.gtAppLifecycle={activate(){refresh(false)},deactivate(){document.querySelectorAll('audio,video').forEach(x=>x.pause())},beforeLeave(){return !actionBusy},dispose(){++epoch;clearInterval(timer);clearMedia();graff.dispose?.()},async addSample(sample){const start=Date.now();while(!state.repo||state.loading){if(Date.now()-start>15000)throw Error('Yudo could not finish loading. Open Yudo and try again.');await new Promise(resolve=>setTimeout(resolve,50));}if(!state.session)throw Error('Sign in to Yudo first.');draft=draft||getDraft();if(draft.samples.length>=3)throw Error('Your Yudo profile already has three samples.');draft.samples.push(sample);state.editing=true;state.step=3;await saveDraft();render()}};
